                        minimax: '/static/svg/minimax.svg',
                        grok: '/static/svg/XAI.svg',
                        xai: '/static/svg/XAI.svg',
                        qwen: '/static/svg/qwen.svg',
                        dashscope: '/static/svg/qwen.svg',
                        xiaomi: '/static/svg/xiaomi.svg',
